query getSplitSystemCombinations($fbal_ids: [String]!) {
  splitSystemCombinations: splitSystemCombinationsByFbal(ids: $fbal_ids) {
    id
    pubCount
    symbol
    stocksCount
    componentAlleles(condition: {isAlleleof: true}) {
      ...FullAllele
      __typename
    }
    __typename
  }
}

